package com.wesbos.homehq;

import android.os.Bundle;
import android.webkit.JavascriptInterface;
import android.webkit.WebView;
import android.graphics.*;
import android.net.Uri;
import android.provider.MediaStore;
import org.json.*;
import java.io.*;
import java.util.*;

/** Separate test APK/UID. Never opens the household application's storage. */
public final class SlideshowTestActivity extends MainActivity {
  private final List<Uri> created=new ArrayList<>();
  private PhotoStore own;private LocalMedia local;private String result="{}";
  @Override public void onCreate(Bundle state){super.onCreate(state);try{
    own=new PhotoStore(this);own.clear();local=new LocalMedia(this,own);
    for(int i=0;i<5;i++){try(InputStream input=getAssets().open("synthetic/"+new String[]{"marigolds","dog","cat","lake","orchard"}[i]+".png")){String id=own.importImage(LocalMedia.read(input,PhotoPolicy.MAX_DOWNLOAD));if(i==1)own.keeper(id,true);}}
    for(int i=0;i<2;i++){Bitmap bitmap=Bitmap.createBitmap(600,900,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(bitmap);Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG);canvas.drawColor(i==0?Color.rgb(231,212,173):Color.rgb(217,217,200));paint.setColor(Color.rgb(189,112,72));canvas.drawCircle(i==0?420:150,180,95,paint);paint.setColor(Color.rgb(119,131,107));Path hills=new Path();hills.moveTo(0,650);hills.cubicTo(120,350,330,650,600,430);hills.lineTo(600,900);hills.lineTo(0,900);hills.close();canvas.drawPath(hills,paint);paint.setColor(Color.rgb(61,91,76));canvas.drawRect(0,750,600,900,paint);paint.setColor(Color.rgb(234,195,144));canvas.drawRect(i==0?260:160,500,i==0?340:440,800,paint);ByteArrayOutputStream out=new ByteArrayOutputStream();bitmap.compress(Bitmap.CompressFormat.JPEG,90,out);bitmap.recycle();String id=own.importImage(out.toByteArray());own.keeper(id,true);}
    getSharedPreferences("skylit-photo-mail",MODE_PRIVATE).edit().putInt("days",0).putInt("maximum",200).apply();own.prune(0,200);
    java.lang.reflect.Field field=MainActivity.class.getDeclaredField("dashboard");field.setAccessible(true);((WebView)field.get(this)).addJavascriptInterface(new Checks(),"SkylitTest");
  }catch(Exception e){result="{\"setupFailed\":true}";}}
  private File fixture(String name) throws Exception {File file=new File(getCacheDir(),name);try(InputStream input=getAssets().open("synthetic/"+name);FileOutputStream out=new FileOutputStream(file)){out.write(LocalMedia.read(input,32*1024*1024));}return file;}
  private void check(boolean condition,String label)throws Exception {if(!condition)throw new IOException(label);}
  public final class Checks {
    @JavascriptInterface public String nativeChecks(){try{
      File scratch=new File(getCacheDir(),"native-checks");scratch.mkdirs();PhotoStore store=new PhotoStore(scratch,getSharedPreferences("isolated-checks",MODE_PRIVATE));store.clear();JSONObject checks=new JSONObject();byte[] image;try(InputStream input=getAssets().open("synthetic/marigolds.png")){image=LocalMedia.read(input,PhotoPolicy.MAX_DOWNLOAD);}String first=store.importImage(image);check(!first.isEmpty(),"image import");check(store.keeper(first,true),"keeper");JSONArray rows=new JSONArray(getSharedPreferences("isolated-checks",MODE_PRIVATE).getString("items","[]"));rows.getJSONObject(0).put("at",1);getSharedPreferences("isolated-checks",MODE_PRIVATE).edit().putString("items",rows.toString()).commit();store.prune(7,5);check(store.list().length()==1,"keeper survives age");check(store.list().getJSONObject(0).getBoolean("keeper"),"keeper status");check(!store.list().getJSONObject(0).getBoolean("recent"),"keeper outside recent");checks.put("keeperSurvivesRetention",true);
      check(store.excludeMany(new JSONArray().put(first).toString(),true),"batch exclusion");check(!store.add(new ByteArrayInputStream(image),System.currentTimeMillis()),"excluded cannot reimport");check(store.excluded().length()==1,"persistent exclusion");check(!store.keeperMany("[\"../bad\"]",true),"malformed batch refused");store.restoreExcluded();checks.put("batchAndExclusions",true);
      store.importOptions(true,false);byte[] second;try(InputStream input=getAssets().open("synthetic/dog.png")){second=LocalMedia.read(input,PhotoPolicy.MAX_DOWNLOAD);}check(store.add(new ByteArrayInputStream(second),System.currentTimeMillis()),"new image");String pending=PhotoStore.digest(second);check(store.list().getJSONObject(0).getBoolean("pending"),"review gates import");check(store.reviewMany(new JSONArray().put(pending).toString(),true),"review approve");checks.put("reviewBeforeDisplay",true);
      File original=new File(getCacheDir(),"dated.jpg");Bitmap bitmap=BitmapFactory.decodeByteArray(image,0,image.length);try(FileOutputStream out=new FileOutputStream(original)){bitmap.compress(Bitmap.CompressFormat.JPEG,90,out);}bitmap.recycle();android.media.ExifInterface exif=new android.media.ExifInterface(original.getAbsolutePath());exif.setAttribute(android.media.ExifInterface.TAG_DATETIME_ORIGINAL,"2020:10:12 12:00:00");exif.setAttribute(android.media.ExifInterface.TAG_GPS_LATITUDE,"37/1,48/1,30/1");exif.setAttribute(android.media.ExifInterface.TAG_GPS_LATITUDE_REF,"N");exif.saveAttributes();store.importOptions(false,true);String dated;try(InputStream input=new FileInputStream(original)){dated=store.importImage(LocalMedia.read(input,PhotoPolicy.MAX_DOWNLOAD));}JSONObject datedRow=null;for(int i=0;i<store.list().length();i++)if(store.list().getJSONObject(i).getString("id").equals(dated))datedRow=store.list().getJSONObject(i);check(datedRow!=null&&datedRow.getString("taken").equals("2020-10-12"),"opt-in capture date");try(InputStream processed=store.open(dated)){android.media.ExifInterface clean=new android.media.ExifInterface(processed);check(clean.getAttribute(android.media.ExifInterface.TAG_GPS_LATITUDE)==null,"GPS stripped");check(clean.getAttribute(android.media.ExifInterface.TAG_DATETIME_ORIGINAL)==null,"raw EXIF stripped");}checks.put("dateOptInAndMetadataRemoval",true);original.delete();
      byte[] clip;try(InputStream input=getAssets().open("synthetic/sample-clip.mp4")){clip=LocalMedia.read(input,32*1024*1024);}String clipMessage=local.clipBytes(clip,()->true);String clipId=PhotoStore.digest(clip);check(own.clip(clipId).isFile(),"clip saved");android.media.MediaExtractor extractor=new android.media.MediaExtractor();try{extractor.setDataSource(own.clip(clipId).getAbsolutePath());check(extractor.getTrackCount()==1,"video audio removed");check("video/avc".equals(extractor.getTrackFormat(0).getString(android.media.MediaFormat.KEY_MIME)),"H264 clip");}finally{extractor.release();}checks.put("mutedVideoImport",true);
      byte[] gif;try(InputStream input=getAssets().open("synthetic/sample-animation.gif")){gif=LocalMedia.read(input,PhotoPolicy.MAX_DOWNLOAD);}local.animated(gif,()->true);check(own.clip(PhotoStore.digest(gif)).isFile(),"GIF converted");checks.put("animatedGifConversion",true);
      File song=fixture("sample-soundtrack.m4a");android.content.ContentValues values=new android.content.ContentValues();values.put(MediaStore.MediaColumns.DISPLAY_NAME,"Skylit-test-soundtrack.m4a");values.put(MediaStore.MediaColumns.MIME_TYPE,"audio/mp4");values.put(MediaStore.MediaColumns.RELATIVE_PATH,"Download/");Uri uri=getContentResolver().insert(MediaStore.Downloads.EXTERNAL_CONTENT_URI,values);created.add(uri);try(OutputStream out=getContentResolver().openOutputStream(uri);InputStream input=new FileInputStream(song)){out.write(LocalMedia.read(input,20*1024*1024));}local.soundtrack(uri);check(local.hasMusic(),"soundtrack saved");checks.put("soundtrackImport",true);
      store.clear();for(File file:scratch.listFiles())file.delete();scratch.delete();result=checks.toString();return result;
    }catch(Exception e){try{result=new JSONObject().put("failed",e.getMessage()==null?"native check":e.getMessage()).toString();}catch(Exception ignored){}return result;}}
    @JavascriptInterface public String summary(){return result;}
    @JavascriptInterface public String ownedDownloads(){JSONArray rows=new JSONArray();try(android.database.Cursor cursor=getContentResolver().query(MediaStore.Downloads.EXTERNAL_CONTENT_URI,new String[]{MediaStore.MediaColumns.DISPLAY_NAME},MediaStore.MediaColumns.OWNER_PACKAGE_NAME+"=?",new String[]{getPackageName()},null)){while(cursor!=null&&cursor.moveToNext())rows.put(cursor.getString(0));}catch(Exception ignored){}return rows.toString();}
    @JavascriptInterface public void cleanShared(){for(Uri uri:created)try{getContentResolver().delete(uri,null,null);}catch(Exception ignored){}created.clear();try(android.database.Cursor cursor=getContentResolver().query(MediaStore.Downloads.EXTERNAL_CONTENT_URI,new String[]{MediaStore.MediaColumns._ID},MediaStore.MediaColumns.OWNER_PACKAGE_NAME+"=?",new String[]{getPackageName()},null)){while(cursor!=null&&cursor.moveToNext()){Uri uri=android.content.ContentUris.withAppendedId(MediaStore.Downloads.EXTERNAL_CONTENT_URI,cursor.getLong(0));getContentResolver().delete(uri,null,null);}}catch(Exception ignored){}}
  }
}
